private void runFlowStep() {
    if (!this.flowActive || this.flowWaiting) {
        return;
    }
    while (true) {
        int i = this.flowIndex;
        if (i >= 5 || !isGranted(i)) {
            break;
        } else {
            this.flowIndex++;
        }
    }
    int i2 = this.flowIndex;
    if (i2 < 5) {
        this.flowWaiting = true;
        executeStep(i2, true);
    } else if (i2 == 5) {
        this.flowWaiting = true;
        openApplicationDetails(REQUEST_FLOW_SETTINGS);
    } else {
        finishFlow();
    }
}
